#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    // Too many arguments (including program name)
    if (argc > 0x41) {
        puts("TOO_MANY");
        return 0;
    }
    // No user‑supplied arguments
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    // Length limit per argument (1024 characters)
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }
    // Compute longest common prefix among all arguments
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    for (int i = 2; i < argc && prefix_len > 0; ++i) {
        size_t j = 0;
        while (j < prefix_len && first[j] == argv[i][j]) {
            ++j;
        }
        prefix_len = j;
    }
    // Output the prefix followed by a newline
    fwrite(first, 1, prefix_len, stdout);
    putchar('\n');
    return 0;
}
